test("concurrent requests for same room produce one 201 and one 409", async (t) => {
  let release;
  const gate = new Promise((resolve) => {
    release = resolve;
  });

  const app = createBookingApp({
    hooks: {
      afterAvailabilityCheck: () => gate,
    },
  });
  t.after(() => app.close());

  // Both requests begin; each awaits afterAvailabilityCheck before writing
  const resultsPromise = Promise.all([
    app.handleRequest({ method: "POST", path: "/bookings", body: MORNING }),
    app.handleRequest({ method: "POST", path: "/bookings", body: { ...MORNING, guestName: "Lin" } }),
  ]);

  // Allow a microtask tick so both reach the gate
  await new Promise((r) => setImmediate(r));

  // Release both requests at once so they race into createBooking
  release();

  const [r1, r2] = await resultsPromise;

  const statuses = [r1.status, r2.status].sort();
  assert.deepEqual(statuses, [201, 409]);

  // Only one booking's slots should exist in the database
  const slotCount = app.database
    .prepare("SELECT COUNT(*) AS cnt FROM booking_slots WHERE room_id = ?")
    .get(MORNING.roomId);
  assert.equal(slotCount.cnt, 2);

  // No duplicate (room_id, starts_at) rows
  const dups = app.database
    .prepare(
      "SELECT starts_at, COUNT(*) AS cnt FROM booking_slots WHERE room_id = ? GROUP BY starts_at HAVING cnt > 1",
    )
    .all(MORNING.roomId);
  assert.equal(dups.length, 0);
});

